import type { BadgeVariants } from "../badge";
import type { ButtonVariants } from "../button";
import type { VNodeChild } from "vue";
import type { DataRecord, TableColumnOptions } from "./types";
import { h } from "vue";
import Badge from "../badge/Badge.vue";
import Button from "../button/Button.vue";

/** 单元格渲染器：与 TableColumnOptions.render 同签名（column 用于读取字段值） */
type ColumnRender<T extends DataRecord> = (
  record: T,
  index: number,
  column: TableColumnOptions<T>,
) => VNodeChild;

export type DictEntryVariant = BadgeVariants["variant"];

export type DictColumnMapping = Record<
  string | number,
  string | { label: string; variant?: DictEntryVariant }
>;

export interface DictColumnOptions {
  /** 整列统一 Badge 形态；条目级 variant 优先 */
  badge?: DictEntryVariant | true;
}

/** 日期模式串（迷你令牌 yyyy MM dd HH mm ss），如 "yyyy-MM-dd HH:mm" */
export type DateColumnPattern = string;

export interface SerialColumnOptions {
  /** 起始序号，默认 1 */
  base?: number;
}

export interface TableActionButton<T extends DataRecord> {
  text: string | ((record: T, index: number) => string);
  onClick?: (record: T, index: number) => void;
  variant?: ButtonVariants["variant"];
  disabled?: (record: T, index: number) => boolean;
}

export interface ColumnRenders<T extends DataRecord> {
  dict: (mapping: DictColumnMapping, options?: DictColumnOptions) => ColumnRender<T>;
  date: (pattern?: DateColumnPattern) => ColumnRender<T>;
  currency: (currency?: string, locale?: string) => ColumnRender<T>;
  serial: (base?: number) => ColumnRender<T>;
  button: (items: Array<TableActionButton<T> | string>) => ColumnRender<T>;
}

const pad = (value: number) => String(value).padStart(2, "0");

/** 迷你日期令牌格式化，不引入 date-fns；非法输入原样返回 */
function formatDate(input: unknown, pattern: string): VNodeChild {
  const date = input instanceof Date ? input : new Date(input as string | number);
  if (Number.isNaN(date.getTime())) return input as VNodeChild;
  const tokens: Record<string, string> = {
    yyyy: String(date.getFullYear()),
    MM: pad(date.getMonth() + 1),
    dd: pad(date.getDate()),
    HH: pad(date.getHours()),
    mm: pad(date.getMinutes()),
    ss: pad(date.getSeconds()),
  };
  return pattern.replace(/yyyy|MM|dd|HH|mm|ss/g, (token) => tokens[token]!);
}

/**
 * 内置列渲染器工厂（对标 x-render table-columns，v1：dict/date/currency/serial/button）。
 * 返回值直接填入 TableColumnOptions.render；column 参数用于读取字段值。
 * 与 FormRender widget 的 r.xxx() 范式共词根（D10）。
 */
export function columnRenders<T extends DataRecord>(): ColumnRenders<T> {
  return {
    dict(mapping, options) {
      return (record, _index, column) => {
        const raw = (record as Record<string, unknown>)[column.key];
        const entry = mapping[raw as string | number];
        if (entry === undefined) return (raw ?? "") as VNodeChild;

        const label = typeof entry === "string" ? entry : entry.label;
        const entryVariant = typeof entry === "object" ? entry.variant : undefined;
        // Badge 形态：条目级 variant，或整列 badge 简写
        if (entryVariant !== undefined || options?.badge !== undefined) {
          const variant = entryVariant ?? (options?.badge === true ? undefined : options?.badge);
          return h(Badge, { variant }, () => label);
        }
        return label;
      };
    },

    date(pattern = "yyyy-MM-dd") {
      return (record, _index, column) =>
        formatDate((record as Record<string, unknown>)[column.key], pattern);
    },

    currency(currency = "CNY", locale = "zh-CN") {
      return (record, _index, column) => {
        const raw = (record as Record<string, unknown>)[column.key];
        const value = typeof raw === "string" ? Number(raw) : raw;
        if (typeof value !== "number" || Number.isNaN(value)) return raw as VNodeChild;
        return new Intl.NumberFormat(locale, { style: "currency", currency }).format(value);
      };
    },

    serial(base = 1) {
      return (_record, index) => index + base;
    },

    button(items) {
      return (record, index) => {
        if (items.length === 0) return "";
        return h(
          "div",
          { class: "flex items-center gap-1" },
          items.map((item) => {
            const action = typeof item === "string" ? { text: item } : item;
            return h(
              Button,
              {
                size: "sm",
                variant: action.variant ?? "link",
                disabled: action.disabled?.(record, index),
                onClick: () => action.onClick?.(record, index),
              },
              () => (typeof action.text === "function" ? action.text(record, index) : action.text),
            );
          }),
        );
      };
    },
  };
}

import type { DataRecord, TableColumnOptions } from "./types";

/**
 * 列定义辅助：补全泛型推导，便于把列配置抽到独立文件。
 *
 * 纯类型辅助，原样返回入参——裸数组同样可直接传给 defineTable（无需此函数）。
 */
export function defineColumns<T extends DataRecord = DataRecord>(
  columns: TableColumnOptions<T>[],
): TableColumnOptions<T>[] {
  return columns;
}

import { useTableRender } from "./useTableRender";
import type { DataRecord, DefineTableOptions, TableRenderDefinition } from "./types";

/**
 * 聚合入口：单次调用完成「列定义 + 数据内核 + 分页排序状态 + 实例动作」。
 *
 * 返回值直接传给 `<TableRender :definition="def" />`；
 * 须在组件 setup 中调用（TanStack useVueTable 约束）。
 */
export function defineTable<T extends DataRecord>(
  config: DefineTableOptions<T>,
): TableRenderDefinition<T> {
  return useTableRender<T>(config);
}

export { default as TableRender } from "./TableRender.vue";
export { columnRenders } from "./column-renders";
export type {
  ColumnRenders,
  DictColumnMapping,
  DictColumnOptions,
  DictEntryVariant,
  SerialColumnOptions,
  TableActionButton,
} from "./column-renders";
export { defineColumns } from "./define-columns";
export { defineTable } from "./define-table";
export { useTableRender } from "./useTableRender";
export type {
  DataRecord,
  DefineTableOptions,
  PageableOptions,
  SortableOptions,
  TableColumnOptions,
  TableLoadParams,
  TableRenderDefinition,
  UseTableRenderOptions,
} from "./types";

import type { Table as TanstackTable } from "@tanstack/vue-table";
import type { MaybeRefOrGetter, VNodeChild } from "vue";

/** 任意数据行（表格是弱类型数据容器，行结构由调用方的 T 决定） */
export interface DataRecord {
  [key: string]: any;
}

/**
 * 列配置。
 *
 * 命名总纲（D10）：能力/性质用 `-able` 形容词（sortable/ellipsis），
 * 配置值用名词（title/align/width），无 `allow-*`。
 */
export interface TableColumnOptions<T extends DataRecord = DataRecord> {
  /** 列标识，同时作为默认取值字段 */
  key: string;
  title: string;
  align?: "left" | "center" | "right";
  width?: number | string;
  /** 自定义单元格渲染，取值链 render > formatter > record[key]（R17） */
  render?: (record: T, index: number, column: TableColumnOptions<T>) => VNodeChild;
  /** 纯数据格式化；render 存在时被忽略 */
  formatter?: (record: T) => string | number | Date | undefined;
  /** 超宽截断 + 原生 title 提示（R15） */
  ellipsis?: boolean;
  /** 是否可排序（能力开关） */
  sortable?: boolean;
  /** 初始排序方向；需 sortable: true，否则 DEV 警告并忽略（R7） */
  defaultSort?: "asc" | "desc";
}

export interface PageableOptions {
  /** 1-based 页码（对外 API 唯一口径） */
  pageIndex: number;
  pageSize: number;
  total: number;
  /** 只读：状态投影不允许调用方直接改写每页条数选项 */
  pageSizeOpts: readonly number[];
}

export interface SortableOptions {
  key: string;
  direction: "asc" | "desc";
}

/** onLoad 入参：数据协议与 x-render 同构，request 生态由调用方自理 */
export interface TableLoadParams<T extends DataRecord = DataRecord> {
  /** 搜索表单值，v1 恒 {}（二期接 FormRender） */
  form: DataRecord;
  page: PageableOptions;
  /** 无排序或已取消排序时为 undefined */
  sort?: SortableOptions;
  /** 回写数据；total 缺省时保留旧值（R10） */
  update: (data: T[], total?: number) => void;
}

/** defineTable 的声明式配置 */
export interface DefineTableOptions<T extends DataRecord = DataRecord> {
  columns: TableColumnOptions<T>[];
  /** 服务端模式数据源；与 data 二选一，onLoad 优先 */
  onLoad?: (params: TableLoadParams<T>) => void | Promise<unknown>;
  /** 静态模式数据源（本地分页/排序） */
  data?: T[];
  /** 是否在挂载后自动加载，默认 true；仅服务端模式生效 */
  autoLoad?: boolean;
  pageSize?: number;
  pageSizeOpts?: number[];
}

/** useTableRender 的入参：data 额外支持 ref/getter（拆分模式下 props 天然响应式） */
export interface UseTableRenderOptions<T extends DataRecord = DataRecord> extends Omit<
  DefineTableOptions<T>,
  "data"
> {
  data?: MaybeRefOrGetter<T[] | undefined>;
}

/** defineTable / useTableRender 的返回物：列配置 + 引擎实例 + 只读状态 + 实例动作 */
export interface TableRenderDefinition<T extends DataRecord = DataRecord> {
  columns: TableColumnOptions<T>[];
  /** TanStack 表格实例（逃逸舱口） */
  table: TanstackTable<T>;
  page: Readonly<PageableOptions>;
  sort: Readonly<{ value: SortableOptions | undefined }>;
  loading: Readonly<{ value: boolean }>;
  /** 重新加载；resetPage 为 true 时先回到第 1 页（R12） */
  reload: (resetPage?: boolean) => void;
  /** 排序三态切换：无 → asc → desc → 取消（R8） */
  toggleSort: (key: string) => void;
  setPageIndex: (pageIndex: number) => void;
  setPageSize: (pageSize: number) => void;
}

import type { ColumnDef } from "@tanstack/vue-table";
import { onMounted, reactive, readonly, ref, shallowRef, toValue, watch } from "vue";
import {
  getCoreRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useVueTable,
} from "@tanstack/vue-table";
import type {
  DataRecord,
  SortableOptions,
  TableRenderDefinition,
  UseTableRenderOptions,
} from "./types";

const DEFAULT_PAGE_SIZE_OPTS = [10, 20, 50, 100];

/** DEV 兜底提示：生产构建静默，只留可读的降级行为（R1–R7） */
function warn(message: string) {
  if (import.meta.env.DEV) console.warn(`[tu-design] <TableRender> ${message}`);
}

/**
 * 表格数据内核：TanStack 无头引擎组装 + 1-based 对外投影 + 实例动作。
 *
 * 状态真相源是 TanStack 引擎（pageIndex 为 0-based），
 * `page`/`sort` 是对外的 1-based 只读投影，由 watch 同步。
 */
export function useTableRender<T extends DataRecord>(
  options: UseTableRenderOptions<T>,
): TableRenderDefinition<T> {
  const columns = options.columns;
  // 传入 onLoad 即服务端模式：分页/排序交由数据源，引擎不做本地加工
  const serverMode = typeof options.onLoad === "function";

  if (columns.length === 0) warn("columns 为空，表格将没有表头。");
  if (serverMode && options.data !== undefined) {
    warn("onLoad 与 data 不能同时传入，已按 onLoad（服务端模式）处理。");
  }

  const page = reactive({
    pageIndex: 1,
    pageSize: options.pageSize ?? 10,
    total: 0,
    pageSizeOpts: options.pageSizeOpts ?? DEFAULT_PAGE_SIZE_OPTS,
  });
  // defaultSort：静态模式进 TanStack 初始 sorting，服务端模式进首载 sort 参数
  const defaults = columns.filter((column) => column.defaultSort !== undefined);
  if (defaults.length > 1) {
    warn(`多列 defaultSort 仅首列 "${defaults[0].key}" 生效，其余已忽略。`);
  }
  if (defaults[0] && defaults[0].sortable !== true) {
    warn(`列 "${defaults[0].key}" 的 defaultSort 需要同时开启 sortable，已忽略。`);
  }
  const sorted = defaults.find((column) => column.sortable === true);
  const sort = ref<SortableOptions | undefined>(
    sorted ? { key: sorted.key, direction: sorted.defaultSort! } : undefined,
  );
  const loading = ref(false);
  const rows = shallowRef<T[]>([]);

  const table = useVueTable({
    get data() {
      return rows.value;
    },
    columns: columns.map<ColumnDef<T>>((column) => ({
      accessorKey: column.key,
      header: column.title,
      enableSorting: column.sortable === true,
    })),
    initialState: {
      sorting: sorted ? [{ id: sorted.key, desc: sorted.defaultSort === "desc" }] : [],
    },
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    manualPagination: serverMode,
    manualSorting: serverMode,
  });

  watch(
    () => table.getState().pagination,
    (pagination) => {
      if (page.pageIndex === pagination.pageIndex + 1 && page.pageSize === pagination.pageSize)
        return;
      page.pageIndex = pagination.pageIndex + 1;
      page.pageSize = pagination.pageSize;
    },
    { immediate: true },
  );

  watch(
    () => table.getState().sorting,
    (sorting) => {
      const next: SortableOptions | undefined = sorting[0]
        ? { key: sorting[0].id, direction: sorting[0].desc ? "desc" : "asc" }
        : undefined;
      // 仅在语义发散时回写：toggleSort 已同步落值，等价对象回写会触发多余的重复加载
      if (sort.value?.key === next?.key && sort.value?.direction === next?.direction) return;
      sort.value = next;
    },
    { immediate: true },
  );

  // 静态数据源：ref/getter 会自动跟随；普通数组为快照，可用 reload() 重同步
  function syncData() {
    const data = toValue(options.data);
    if (data !== undefined && !Array.isArray(data)) {
      warn("data 必须是数组，已按空表处理。");
    }
    // 复制出新引用：就地修改同一个普通数组时 shallowRef 不会触发，行模型会停留在旧快照
    rows.value = Array.isArray(data) ? [...data] : [];
    page.total = rows.value.length;
  }

  watch(() => toValue(options.data), syncData, { immediate: true });

  function setPageIndex(pageIndex: number) {
    table.setPageIndex(Math.max(0, pageIndex - 1));
  }

  function setPageSize(pageSize: number) {
    table.setPageSize(pageSize);
    // TanStack 容量变更后停在最后一页（pageCount-1），R9 要求回到首页
    table.setPageIndex(0);
  }

  /** 排序三态：无 → asc → desc → 取消；非 sortable 列为空操作（R8） */
  function toggleSort(key: string) {
    if (!columns.some((column) => column.key === key && column.sortable === true)) return;

    const current = sort.value;
    const direction =
      current?.key !== key ? "asc" : current.direction === "asc" ? "desc" : undefined;

    // 服务端模式按新排序取数，必须先归位到首页（R8）
    if (serverMode && page.pageIndex !== 1) setPageIndex(1);
    // 同步落值：对外投影不能等 watcher（emit 需要立即读到新排序）
    sort.value = direction ? { key, direction } : undefined;
    table.setSorting(direction ? [{ id: key, desc: direction === "desc" }] : []);
  }

  // 服务端模式：请求序号守卫，乱序返回的旧响应直接丢弃（R6）
  let requestId = 0;

  async function load() {
    const id = ++requestId;
    loading.value = true;
    try {
      await options.onLoad?.({
        form: {},
        page: {
          pageIndex: page.pageIndex,
          pageSize: page.pageSize,
          total: page.total,
          pageSizeOpts: page.pageSizeOpts,
        },
        sort: sort.value,
        update: (data, total) => {
          if (id !== requestId) return;
          rows.value = Array.isArray(data) ? data : [];
          // total 缺省时保留旧值（R10）
          if (typeof total === "number") page.total = total;
        },
      });
    } catch (error) {
      if (id === requestId) console.error("[tu-design] <TableRender> onLoad 执行失败：", error);
    } finally {
      if (id === requestId) loading.value = false;
    }
  }

  // 服务端模式下分页/排序变化即重取数；同一 tick 内多次变更只触发一次
  watch(
    () => (serverMode ? [page.pageIndex, page.pageSize, sort.value] : null),
    () => {
      void load();
    },
  );

  onMounted(() => {
    if (serverMode && (options.autoLoad ?? true)) void load();
  });

  function reload(resetPage = false) {
    if (serverMode) {
      // 归位由分页 watch 触发重载；页码本就为首页时直接重载（避免双请求）
      if (resetPage && page.pageIndex !== 1) setPageIndex(1);
      else void load();
      return;
    }
    if (resetPage) setPageIndex(1);
    syncData();
  }

  return {
    columns,
    table,
    page: readonly(page),
    sort: readonly(sort),
    loading: readonly(loading),
    reload,
    toggleSort,
    setPageIndex,
    setPageSize,
  };
}
